SELECT  T0."empID" AS "SAP Code",  T0."ExtEmpNo" as "Biometric Code",  T0."firstName" as "First Name",  T0."middleName" as "Middle Name",  T0."lastName" as "last Name",  T0."startDate" as "Joining Date", T0."U_ViExDa" as "Visa Expiry Date", (Select "Name" from OUDP where "Code"=T0."dept") as "Department", T2."BPLName" as "Branch Name", T3."name" as "Position Name", T4."Name" as "Nationality", T0."birthDate" as "Date of Birth",  T0."sex" as "Gender", T0."email" as "E-Mail", T0."U_OHC",DAYS_BETWEEN(CURRENT_DATE,T0."U_OHC") as "DaysToExpiry"   FROM OHEM T0  Inner Join HEM10 T1 on T0."empID"= T1."empID"  Inner Join OBPL T2 On T1."BPLId" = T2."BPLId"  LEFT JOIN OCRY T4 ON T0."citizenshp" = T4."Code"  LEFT JOIN OHPS T3 ON T0."position" = T3."posID"  LEFT JOIN OHTR T5 ON T0."termReason" = T5."reasonID"  where DAYS_BETWEEN(CURRENT_DATE,T0."U_OHC") < 60 and "Active"='Y'
